// routePerm is one row of routePermissions.
type routePerm struct {
	Kind    middleware.RouteKind
	Perms   []string
	Planned bool // route of API.openapi.yaml not mounted yet
}

// routeTable adapts routePermissions to middleware.RouteTable (path matching by chi pattern).
type routeTable struct{ m *middleware.PatternMatcher }

func newRouteTable() *routeTable {
	m := middleware.NewPatternMatcher()
	for k, v := range routePermissions {
		method, pattern, _ := strings.Cut(k, " ")
		m.Add(method, pattern, middleware.RouteEntry{Kind: v.Kind, Perms: v.Perms})
	}
	return &routeTable{m: m}
}

// Lookup implements middleware.RouteTable.
func (t *routeTable) Lookup(method, path string) (middleware.RouteEntry, bool) {
	return t.m.Lookup(method, path)
}

// RouteTable returns the route table for the token gate (middleware.TokenGate.Routes).
func RouteTable() middleware.RouteTable { return newRouteTable() }
